  if (rawLines.length <= 1) {
    console.log('[PASTE] single line, letting default paste handle it (oninput will fire markDirty)');
    return;
  }

  // ── Multi-value paste: fill DOM inputs in the same column downward ──
  e.preventDefault();

  const col = input.dataset.col;
  const sortedIdx = parseInt(input.dataset.sortedIdx);
  const colInputs = [...$('tableBody').querySelectorAll('input[data-col="' + esc(col) + '"]')]
    .sort((a, b) => parseInt(a.dataset.sortedIdx) - parseInt(b.dataset.sortedIdx));

  let filled = 0;
  for (let i = 0; i < rawLines.length; i++) {
    const val = rawLines[i].trim();
    if (val === '') continue;
    const target = colInputs[sortedIdx + i];
    if (!target) break; // no more rows in this column
    target.value = val;
    // 不修改 dataset.original，保留渲染时设置的原始值，
    // 这样 hasUnsavedChanges() 和 applyChanges() 才能正确检测到粘贴带来的修改
    filled++;
  }

  // Mark all filled cells as needing save (they differ from original data)
  for (let i = 0; i < filled; i++) {
    const target = colInputs[sortedIdx + i];
    if (target) {
      const td = target.closest('td');
      if (td) td.classList.add('modified');
    }
  }

  updateSaveState();
  console.log('[PASTE] filled:', filled, 'values into column:', col);
  toast(`已填入 ${filled} 个值到 "${col}" 列，点击「✏️ 应用修改」保存`);
});

