document.addEventListener('paste', function (e) {
  // Find the editable input — either the event target itself or the activeElement
  let input = null;
  if (e.target.tagName === 'INPUT' && e.target.dataset.col) {
    input = e.target;
  } else if (document.activeElement && document.activeElement.tagName === 'INPUT' && document.activeElement.dataset.col) {
    input = document.activeElement;
  }

  console.log('[PASTE] target input:', input ? `col=${input.dataset.col}, sortedIdx=${input.dataset.sortedIdx}` : 'NOT FOUND');
  if (!input) return; // not pasting into our editable cell

  const pasteText = (e.clipboardData || window.clipboardData).getData('text');
  console.log('[PASTE] raw text length:', pasteText ? pasteText.length : 0, 'first 100 chars:', JSON.stringify(pasteText ? pasteText.substring(0, 100) : ''));
  if (!pasteText) return;

  // Normalize line endings and split
  const rawLines = pasteText.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');

  // Remove trailing empty lines
  while (rawLines.length && rawLines[rawLines.length - 1].trim() === '') rawLines.pop();

  console.log('[PASTE] line count:', rawLines.length, 'lines:', JSON.stringify(rawLines.slice(0, 5)));
  // If only one line, let the default paste behavior handle it (single value)
  if (rawLines.length <= 1) {
    console.log('[PASTE] single line, letting default paste handle it (oninput will fire markDirty)');
    return;
  }

  // ── Multi-value paste: fill DOM inputs in the same column downward ──
