sorted.forEach((row, sortedIdx) => {
  const dataIdx = data.indexOf(row);
  bodyHtml += `<tr>`;
  bodyHtml += `<td class="col-index">${sortedIdx + 1}</td>`;
  columns.forEach(col => {
    if (computedFields[col]) {
      // ── computed cell (read-only) ──
      let val = normalizeValue(row[col]);
      bodyHtml += `<td class="computed">${val}</td>`;
    } else {
      // ── editable cell ──
      let val = normalizeValue(row[col]);
      let isMod = original && dataIdx >= 0 && dataIdx < original.length &&
        JSON.stringify(row) !== JSON.stringify(original[dataIdx]);
      bodyHtml += `<td class="editable${isMod ? ' modified' : ''}">`
        + `<input value="${val.replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}"`
        + ` data-col="${esc(col)}" data-sorted-idx="${sortedIdx}" data-original="${esc(val)}"`
        + ` oninput="markDirty(this)" onfocus="this.select()">`
        + `</td>`;
    }
  });
  bodyHtml += `<td><button class="del-btn" onclick="deleteRow(${sortedIdx})" title="删除此行">✕</button></td>`;
  bodyHtml += `</tr>`;
});
$('tableBody').innerHTML = bodyHtml;

// stats
$('statFile').textContent = '📄 ' + (currentFile || '未命名数据');
$('statRows').textContent = `📋 ${data.length} 行 × ${columns.length} 列`;
$('statDirty').textContent = '💡 编辑后点击「✏️ 应用修改」保存到数据模型';

// Undo button: show if original snapshot exists
if (original) {
  $('undoBtn').style.display = '';
  $('undoBtn').disabled = false;
} else {
  $('undoBtn').style.display = 'none';
}

let compKeys = Object.keys(computedFields);

