  const template = data.map(row => {
    const obj = {};
    obj[nameCol] = row[nameCol] ?? '';
    obj['职业'] = row['职业'] ?? '';
    return obj;
  });
  const json = JSON.stringify(template, null, 2);
  saveTemplateFile(json);
}

async function saveTemplateFile(json) {
  const suggested = '曙光英雄_模板.json';
  if ('showSaveFilePicker' in window) {
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: suggested,
        types: [{ description: 'JSON files', accept: { 'application/json': ['.json'] } }]
      });
      const writable = await handle.createWritable();
      await writable.write(json);
      await writable.close();
      toast(`模板已创建: ${handle.name}`);
    } catch (e) {
      if (e.name !== 'AbortError') alert('创建模板失败: ' + e.message);
    }
  } else {
    // Fallback: download
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = Object.assign(document.createElement('a'), { href: url, download: suggested });
    a.click();
    URL.revokeObjectURL(url);
    toast('模板已下载');
  }
}

