    const d = new Date();
    const dateStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    const fileName = `曙光英雄_${dateStr}.json`;

    // 3. 写入模板文件
    const fileHandle = await dirHandle.getFileHandle(fileName, { create: true });
    const writable = await fileHandle.createWritable();
    await writable.write(json);
    await writable.close();

    // 4. 登记到 config.json
    await registerInConfig(dirHandle, fileName, dateStr);

    toast(`模板已创建并登记: ${fileName}`);
  } catch (e) {
    if (e.name !== 'AbortError') alert('创建模板失败: ' + e.message);
  }
}

async function registerInConfig(dirHandle, fileName, dateStr) {
  try {
    const configHandle = await dirHandle.getFileHandle('config.json');
    const file = await configHandle.getFile();
    const config = JSON.parse(await file.text());
    if (!config.dates) config.dates = [];
    const exists = config.dates.some(d => d.file === fileName);
    if (!exists) {
      config.dates.push({ date: dateStr, file: fileName });
      const writable = await configHandle.createWritable();
      await writable.write(JSON.stringify(config, null, 2));
      await writable.close();
