async function saveTemplateFile(json) {
  // Fallback for browsers without File System Access API
  if (!('showDirectoryPicker' in window)) {
    const suggested = '曙光英雄_模板.json';
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = Object.assign(document.createElement('a'), { href: url, download: suggested });
    a.click();
    URL.revokeObjectURL(url);
    toast('模板已下载');
    return;
  }

  try {
    // 1. Pick the game data directory (e.g. 曙光英雄). Browser remembers via id.
    const dirHandle = await window.showDirectoryPicker({
      id: 'sg-template-dir',
      mode: 'readwrite'
    });

    // 2. Build filename: 曙光英雄_YYYY-MM-DD.json, bump suffix if taken
    const d = new Date();
    const dateStr = d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
    let fileName = `曙光英雄_${dateStr}.json`;
    let counter = 1;
    while (true) {
      const testName = counter === 1
        ? `曙光英雄_${dateStr}.json`
        : `曙光英雄_${dateStr}_${counter}.json`;
